import sys
input = sys.stdin.readline

def solve():
	(R, C, Q) = map(int, input().split())
	s = []
	for _ in range(R):
		s.append(list(input().strip()))
	t = []
	for i in range(C):
		for j in range(R):
			t.append(s[j][i])
	total = t.count('*')
	current = t[total:].count('*')
	for _ in range(Q):
		(x, y) = map(int, input().split())
		x -= 1
		y -= 1
		now = y * R + x
		if t[now] == '*':
			if now >= total:
				current -= 1
			t[now] = '.'
			total -= 1
			if t[total] == '*':
				current += 1
		else:
			if now >= total:
				current += 1
			t[now] = '*'
			if t[total] == '*':
				current -= 1
			total += 1
		print(current)
solve()
